files.content:
@custom-variant dark (&:is(.dark *));
@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-chart-1: var(--chart-1);
  --color-chart-2: var(--chart-2);
  --color-chart-3: var(--chart-3);
  --color-chart-4: var(--chart-4);
  --color-chart-5: var(--chart-5);
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
  --font-sans: var(--app-font);
  --font-heading: var(--app-font);
  --font-mono: var(--font-geist-mono, "Geist Mono", monospace);
  --radius-sm: calc(var(--radius) * .6);
  --radius-md: calc(var(--radius) * .8);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) * 1.4);
  --radius-2xl: calc(var(--radius) * 1.8);
  --radius-3xl: calc(var(--radius) * 2.2);
  --radius-4xl: calc(var(--radius) * 2.6);
}
:root {
  --background: #fafafa;
  --foreground: #171717;
  --card: #ffffff;
  --card-foreground: #171717;
  --popover: #ffffff;
  --popover-foreground: #171717;
  --primary: #171717;
  --primary-foreground: #ffffff;
  --secondary: #f1f1f1;
  --secondary-foreground: #171717;
  --muted: #f5f5f5;
  --muted-foreground: #686868;
  --accent: #eeeeee;
  --accent-foreground: #171717;
  --destructive: #c92b2b;
  --destructive-foreground: #ffffff;
  --border: #e5e5e5;
  --input: #d9d9d9;
  --ring: #737373;
  --chart-1: #0070f3;
  --chart-2: #38a169;
  --chart-3: #ea7d20;
  --chart-4: #8b5cf6;
  --chart-5: #e83e8c;
  --sidebar: #fafafa;
  --sidebar-foreground: #171717;
  --sidebar-primary: #171717;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #eeeeee;
  --sidebar-accent-foreground: #171717;
  --sidebar-border: #e5e5e5;
  --sidebar-ring: #737373;
  --app-font: var(--font-geist-sans, "Geist", system-ui, sans-serif);
  --radius: 6px;
  --border-width: 1px;
  --spacing: 4px;
  --control-height: 36px;
  --text-scale: 1;
  --theme-shadow: none;
}
.dark {
  --background: #000000;
  --foreground: #ededed;
  --card: #0a0a0a;
  --card-foreground: #ededed;
  --popover: #111111;
  --popover-foreground: #ededed;
  --primary: #ededed;
  --primary-foreground: #0a0a0a;
  --secondary: #1a1a1a;
  --secondary-foreground: #ededed;
  --muted: #171717;
  --muted-foreground: #a1a1a1;
  --accent: #242424;
  --accent-foreground: #ededed;
  --destructive: #ff6666;
  --destructive-foreground: #171717;
  --border: #292929;
  --input: #363636;
  --ring: #a1a1a1;
  --sidebar: #0a0a0a;
  --sidebar-foreground: #ededed;
  --sidebar-primary: #ededed;
  --sidebar-primary-foreground: #171717;
  --sidebar-accent: #1f1f1f;
  --sidebar-accent-foreground: #ededed;
  --sidebar-border: #292929;
  --sidebar-ring: #a1a1a1;
}
@layer base {
  * { border-color: var(--border); }
  html { font-size: calc(16px * var(--text-scale)); color-scheme: light; }
  html.dark { color-scheme: dark; }
  body { margin: 0; background: var(--background); color: var(--foreground); font-family: var(--app-font); }
  button, input, textarea, select { font-family: inherit; }
  button:not(:disabled), [role="button"]:not([aria-disabled="true"]) { cursor: pointer; }
  :focus-visible { outline: 2px solid var(--ring); outline-offset: 3px; }
  ::selection { background: var(--primary); color: var(--primary-foreground); }
}
[data-slot="button"] { height: var(--control-height); border-radius: var(--radius); font-size: .8125rem; box-shadow: var(--theme-shadow); }
[data-slot="button"][data-size="sm"], [data-slot="button"][data-size="icon-sm"] { height: calc(var(--control-height) - 4px); }
[data-slot="button"][data-size="xs"], [data-slot="button"][data-size="icon-xs"] { height: calc(var(--control-height) - 8px); }
[data-slot="button"][data-size="lg"], [data-slot="button"][data-size="icon-lg"] { height: calc(var(--control-height) + 4px); }
[data-slot="button"][data-size^="icon"] { width: var(--control-height); padding: 0; }
[data-slot="button"][data-size="icon-sm"] { width: calc(var(--control-height) - 4px); }
[data-slot="button"][data-variant="outline"] { border-width: var(--border-width); background: var(--card); }
[data-slot="button"][data-variant="outline"]:hover { background: var(--muted); }
[data-slot="input"], [data-slot="select-trigger"], [data-slot="native-select"] { height: var(--control-height); border-radius: var(--radius); border-width: var(--border-width); background: var(--card); font-size: .8125rem; }
[data-slot="textarea"], [data-slot="card"], [data-slot="dialog-content"], [data-slot="popover-content"], [data-slot="dropdown-menu-content"], [data-slot="select-content"] { border-width: var(--border-width); border-radius: var(--radius); }
[data-slot="card"] { box-shadow: var(--theme-shadow); background: var(--card); }
[data-slot="badge"] { border-radius: calc(var(--radius) * .7); }
[data-slot="table-head"] { color: var(--muted-foreground); font-size: .75rem; font-weight: 500; }
[data-slot="table-cell"] { font-size: .8125rem; }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; scroll-behavior: auto !important; } }
